{"sentences": [{"sentence_id": "s1", "sentence": "There are 123 trials testing CD20-targeting drugs across all diseases, with 59 in Phase 3 and 24 in Phase 4.", "cites": ["NCT06677710"]}, {"sentence_id": "s2", "sentence": "Roche leads with 35 trials, followed by Novartis with 16 and TG Therapeutics with 10.", "cites": ["NCT06677710"]}, {"sentence_id": "s3", "sentence": "Approved CD20 drugs include ocrelizumab, ofatumumab, and ublituximab for multiple sclerosis, and rituximab for neuromyelitis optica spectrum disorder in Japan.", "cites": ["NCT06677710"]}, {"sentence_id": "s4", "sentence": "Eight trials targeting CD20 have stopped, including for business reasons (NCT06677710), slow enrollment (NCT04877457), and geopolitical conflict (NCT05208840).", "cites": ["NCT06677710", "NCT04877457", "NCT05208840"]}, {"sentence_id": "s5", "sentence": "Rituximab, ocrelizumab, ofatumumab, and ublituximab are approved drugs in the CD20 class, with indications in multiple sclerosis and B-cell malignancies.", "cites": ["FDA:3e5b7e82-f018-4eaf-ae78-d6145a906b20", "FDA:9da42362-3bb5-4b83-b4bb-b59fd4e55f0d", "FDA:6a8a3f53-2062-48ff-9dbe-b939df133ca3"]}, {"sentence_id": "s6", "sentence": "Recent literature indicates that disease control under anti-CD20 therapy is pharmacologically maintained rather than biologically resolved, with uncertain outcomes upon discontinuation (PMID:42991313).", "cites": ["PMID:42991313"]}, {"sentence_id": "s7", "sentence": "CD20 antigen loss is reported as a mechanism of immune escape in diffuse large B-cell lymphoma after anti-CD20 therapy (PMID:42967966).", "cites": ["PMID:42967966"]}, {"sentence_id": "s8", "sentence": "Patients on anti-CD20 therapy are at increased risk of non-PML neuroinvasive infections and persistent COVID-19 (PMID:42947820, PMID:42974628).", "cites": ["PMID:42947820", "PMID:42974628"]}, {"sentence_id": "s9", "sentence": "The median stop-risk for CD20 trials across all diseases is 0.24, based on 29 trials with a typical risk of 0.128.", "cites": ["RISK:cd20:all"]}, {"sentence_id": "s10", "sentence": "CD20-targeting drugs face competition from emerging therapies like CD19 CAR-T and bispecific antibodies, but remain central in B-cell-driven conditions.", "cites": ["NCT06677710", "NCT06503094"]}], "sources": [{"id": "NCT06677710", "text": "{"nct":"NCT06677710","title":"IDP-023 g-NK Cells Plus Ocrelizumab in Patients With Progressive Multiple Sclerosis","state":"stopped","drug":"ocrelizumab","start_year":2026,"end_year":2026,"phase":"1","overall_status":"SUSPENDED","why_stopped":"Business Reasons","lead_sponsor":"Indapta Therapeutics, INC."}
